<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Leaderboard – MeldeVerkehr</title><style>body{font-family:system-ui,sans-serif;background:#f5f7fa;color:#172033;margin:0}main{max-width:800px;margin:28px auto;padding:20px}.card{background:#fff;border:1px solid #dfe5ec;border-radius:15px;padding:20px}table{width:100%;border-collapse:collapse}td,th{padding:9px;border-bottom:1px solid #e5e9ee;text-align:left}.muted{color:#66758a}</style></head><body><main><p><a href="/community">← Community</a></p><h1>Leaderboard</h1><p class="muted">Nur Nutzer mit ausdrücklichem Opt-in erscheinen. Punkte basieren auf qualitätsgewichteten Reputationsevents, nicht bloß auf Rohmenge.</p><section class="card"><table><tr><th>#</th><th>Nutzer</th><th>Punkte</th></tr><?php foreach($rows as $r):?><tr><td><?= $e($r['rank']) ?></td><td><a href="/community/u/<?= rawurlencode($r['username']) ?>">@<?= $e($r['username']) ?></a></td><td><?= $e($r['points']) ?></td></tr><?php endforeach;?></table></section></main></body></html>